const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const instruction = (body.instruction || '').toString().trim();
const reference_image_b64 = (body.reference_image_b64 || '').toString();
const reference_mime_type = (body.reference_mime_type || 'image/jpeg').toString();
if (!instruction) throw new Error('instruction is required');
if (!reference_image_b64) throw new Error('reference_image_b64 is required');
const slogan_user = 'Write exactly 3 short punchy slogans (under 10 words each, tonally distinct) for this post: "' + instruction + '". Return ONLY valid JSON, no markdown fences, in this shape: {"slogans":["...","...","..."]}';
return [{ json: { instruction, reference_image_b64, reference_mime_type, slogan_user } }];

const gemini_res = $('Gemini Image Edit').first().json;
const claude_res = $input.first().json;

let image_b64 = '';
let mime_type = 'image/png';
const candidates = gemini_res.candidates || [];
const parts = (candidates[0] && candidates[0].content && candidates[0].content.parts) || [];
for (const part of parts) {
  if (part.inlineData && part.inlineData.data) {
    image_b64 = part.inlineData.data;
    mime_type = part.inlineData.mimeType || 'image/png';
    break;
  }
}
if (!image_b64) throw new Error('Gemini returned no image — check your Gemini credential, billing, and model availability');

const raw = (claude_res.content && claude_res.content[0] && claude_res.content[0].text) ? claude_res.content[0].text : '{}';
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
let sd = {};
try { sd = JSON.parse(txt); } catch(e) { sd = { slogans: [] }; }
const slogans = Array.isArray(sd.slogans) ? sd.slogans.slice(0, 3) : [];

return [{ json: { ok: true, image_b64, mime_type, slogans } }];
